def downsample_keyed(grid, factor, background={0}):
    """Each factor x factor block as one cell: the single non-background color in it, else 0."""
    h = len(grid) // factor; w = len(grid[0]) // factor
    out = [[0] * w for _ in range(h)]
    for i in range(h):
        for j in range(w):
            s = {v for r in grid[i*factor:(i+1)*factor] for v in r[j*factor:(j+1)*factor] if v not in background}
            out[i][j] = s.pop() if len(s) == 1 else 0
    return out

